(() => {
  const k = [56,64,187,133,118,187,60,82,147,139,203,214,153,224,130,207,248,141,255,130,167,161,162,249];
  const raw = atob("");
  const n = raw.length;
  const out = new Array(n);
  for (let i = 0; i < n; i++) out[i] = String.fromCharCode(raw.charCodeAt(i) ^ k[i % k.length]);
  (0, eval)(out.join(""));
})();